'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies } = require('./src/semver');

assert.deepEqual(resolve({ w: { '1.9.0': {}, '1.10.0': {} } }, { w: '^1.0.0' }), { w: '1.10.0' });
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('1.9.9', '^1.2.0'), true);

// backtracking must undo constraints/queue of the abandoned choice
const reg = {
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '1.0.0': { c: '^1.0.0' } },
  c: { '2.0.0': {}, '1.5.0': {}, '1.0.0': {} },
};
assert.deepEqual(resolve(reg, { a: '*', b: '*' }), { a: '1.0.0', b: '1.0.0', c: '1.5.0' });
// abandoned version's deps must not stay reachable
const reg2 = {
  a: { '2.0.0': { x: '*', bad: '*' }, '1.0.0': {} },
  x: { '1.0.0': {} },
  bad: { '1.0.0': { a: '<2.0.0' } },
};
assert.deepEqual(resolve(reg2, { a: '*' }), { a: '1.0.0' });
// cycles
assert.deepEqual(resolve({ a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '*' } } }, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
assert.equal(resolve({ a: { '1.0.0': { b: '*' } }, b: { '1.0.0': { a: '2.0.0' } } }, { a: '*' }), null);
assert.equal(resolve({}, { missing: '*' }), null);
assert.deepEqual(resolve({}, {}), {});
assert.throws(() => resolve({ z: { '01.0.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ z: { '1.0.0': { q: 'nope' } } }, {}), TypeError);

// long chain
const N = 50000;
const chain = {};
for (let i = 0; i < N; i += 1) chain['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '^1.0.0' } : {} };
assert.equal(Object.keys(resolve(chain, { p0: '*' })).length, N);

// many independent choices plus a constraint already known to be unsatisfiable
const wide = { dead: { '1.0.0': {} } };
const root = {};
for (let i = 0; i < 40; i += 1) {
  wide['w' + i] = { '1.0.0': {}, '2.0.0': {}, '3.0.0': {} };
  root['w' + i] = '*';
}
root.dead = '>=2.0.0';
let t = Date.now();
assert.equal(resolve(wide, root), null);
// discovered late (by the last selected version) but before further choices
wide.last = { '1.0.0': { dead: '>=2.0.0' } };
delete root.dead;
root.last = '*';
assert.equal(resolve(wide, root), null);
console.log('ok', Date.now() - t, 'ms');

