'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

// Literal reading of the contract: chronological DFS, lazy conflict detection.
function reference(registry, root) {
  function search(selected, constraints, queue, cursor) {
    while (cursor < queue.length && selected.has(queue[cursor])) cursor += 1;
    if (cursor === queue.length) return Object.fromEntries(selected);
    const name = queue[cursor];
    const versions = Object.keys(registry[name] || {}).sort((a, b) => compare(b, a))
      .filter(v => constraints.filter(c => c.name === name).every(c => satisfies(v, c.range)));
    for (const v of versions) {
      const sel = new Map(selected).set(name, v);
      const deps = Object.entries(registry[name][v]);
      const cons = constraints.concat(deps.map(([n, r]) => ({ name: n, range: r })));
      if (deps.some(([n, r]) => sel.has(n) && !satisfies(sel.get(n), r))) continue;
      const found = search(sel, cons, queue.concat(deps.map(([n]) => n)), cursor + 1);
      if (found) return found;
    }
    return null;
  }
  const entries = Object.entries(root);
  return search(new Map(), entries.map(([n, r]) => ({ name: n, range: r })), entries.map(([n]) => n), 0);
}

let seed = 12345;
const rand = n => { seed = (Math.imul(seed, 1103515245) + 12345) >>> 0; return (seed >>> 8) % n; };
const ranges = ['*', '*', '*', '>=1.0.0', '<3.0.0', '^1.0.0', '^2.0.0', '>=1.5.0', '<2.0.0', '~1.0.0', '1.0.0', '^0.1.0', '>3.0.0', '>=1.0.0 <2.5.0'];
const pool = ['0.1.0', '0.1.5', '1.0.0', '1.0.3', '1.5.0', '1.10.0', '2.0.0', '2.5.0', '3.0.0'];
let solved = 0;
for (let iter = 0; iter < 30000; iter += 1) {
  const names = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].slice(0, 2 + rand(7));
  const registry = {};
  for (const n of names) {
    if (rand(25) === 0) continue; // missing package
    registry[n] = {};
    for (const v of pool) {
      if (rand(2) !== 0) continue;
      const deps = {};
      for (const d of names) if (rand(4) === 0) deps[d] = ranges[rand(ranges.length)];
      registry[n][v] = deps;
    }
  }
  const root = {};
  for (const n of names) if (rand(2) === 0) root[n] = ranges[rand(ranges.length)];
  const expected = reference(registry, root);
  if (expected) solved += 1;
  assert.deepEqual(resolve(registry, root), expected, JSON.stringify({ registry, root }));
}
console.log('diff ok, solved', solved);
